create sequence if not exists public.expense_reference_seq;
create or replace function public.generate_expense_reference() returns text language plpgsql volatile security definer set search_path = public as $$ begin return 'EXP-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(nextval('public.expense_reference_seq')::text, 6, '0'); end; $$;
alter table public.transaction_postings alter column transaction_id drop not null;
alter table public.transaction_postings add column if not exists expense_id uuid;
alter table public.transaction_postings drop constraint if exists transaction_postings_posting_kind_check;
alter table public.transaction_postings add constraint transaction_postings_posting_kind_check check (posting_kind in ('ORIGINAL','REVERSAL','EXPENSE','EXPENSE_REVERSAL'));
create unique index if not exists transaction_postings_expense_kind_idx on public.transaction_postings(expense_id, posting_kind) where expense_id is not null;
create index if not exists transaction_postings_expense_idx on public.transaction_postings(expense_id) where expense_id is not null;
alter table public.ledger_entries add column if not exists expense_id uuid;
alter table public.ledger_entries drop constraint if exists ledger_entries_entry_type_check;
alter table public.ledger_entries add constraint ledger_entries_entry_type_check check (entry_type in ('OPENING_BALANCE','TRANSACTION_PRINCIPAL','CUSTOMER_CHARGE','COMMISSION','ADJUSTMENT','REVERSAL','EXPENSE'));
create index if not exists ledger_entries_expense_idx on public.ledger_entries(expense_id) where expense_id is not null;
create table if not exists public.expense_categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null check (char_length(trim(name)) between 2 and 80), created_by uuid not null references auth.users(id) on delete restrict, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (business_id, name));
create index if not exists expense_categories_business_idx on public.expense_categories(business_id, is_active, name);
create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), internal_reference text not null unique default public.generate_expense_reference(), idempotency_key text not null unique default gen_random_uuid()::text, business_id uuid not null references public.businesses(id) on delete restrict, booth_id uuid not null references public.booths(id) on delete restrict, category_id uuid not null references public.expense_categories(id) on delete restrict, description text not null check (char_length(trim(description)) between 2 and 240), amount_pesewas bigint not null check (amount_pesewas > 0), expense_at timestamptz not null default now(), payment_source_account_id uuid not null references public.financial_accounts(id) on delete restrict, payee text, notes text, status text not null default 'PENDING_APPROVAL' check (status in ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','POSTED','REVERSED')), requires_approval boolean not null default true, recorded_by uuid not null references auth.users(id) on delete restrict, submitted_at timestamptz, approved_by uuid references auth.users(id) on delete restrict, approved_at timestamptz, rejected_by uuid references auth.users(id) on delete restrict, rejected_at timestamptz, posted_by uuid references auth.users(id) on delete restrict, posted_at timestamptz, reversed_by uuid references auth.users(id) on delete restrict, reversed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists expenses_business_time_idx on public.expenses(business_id, expense_at desc);
create index if not exists expenses_business_status_idx on public.expenses(business_id, status, expense_at desc);
create index if not exists expenses_business_account_idx on public.expenses(business_id, payment_source_account_id, expense_at desc);
create index if not exists expenses_business_booth_idx on public.expenses(business_id, booth_id, expense_at desc);
alter table public.transaction_postings drop constraint if exists transaction_postings_expense_id_fkey;
alter table public.transaction_postings add constraint transaction_postings_expense_id_fkey foreign key (expense_id) references public.expenses(id) on delete restrict;
alter table public.ledger_entries drop constraint if exists ledger_entries_expense_id_fkey;
alter table public.ledger_entries add constraint ledger_entries_expense_id_fkey foreign key (expense_id) references public.expenses(id) on delete restrict;
create table if not exists public.expense_status_history (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, business_id uuid not null references public.businesses(id) on delete cascade, from_status text, to_status text not null check (to_status in ('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED','POSTED','REVERSED')), reason text, changed_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now());
create index if not exists expense_status_history_expense_idx on public.expense_status_history(expense_id, created_at desc);
create or replace function public.touch_expense_updated_at() returns trigger language plpgsql security definer set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists expenses_updated_at on public.expenses;
create trigger expenses_updated_at before update on public.expenses for each row execute function public.touch_expense_updated_at();
drop trigger if exists expense_categories_updated_at on public.expense_categories;
create trigger expense_categories_updated_at before update on public.expense_categories for each row execute function public.touch_expense_updated_at();
insert into public.expense_categories (business_id,name,created_by) select b.id,c.name,b.owner_id from public.businesses b cross join (values ('Rent'),('Electricity'),('Water'),('Internet and data'),('Staff salaries and wages'),('Transportation'),('Security'),('Office supplies'),('Equipment and repairs'),('Generator fuel'),('Business maintenance'),('Bank charges'),('Other expenses')) c(name) on conflict (business_id,name) do nothing;
alter table public.expense_categories enable row level security;
alter table public.expenses enable row level security;
alter table public.expense_status_history enable row level security;
drop policy if exists "Members can read expense categories" on public.expense_categories;
create policy "Members can read expense categories" on public.expense_categories for select using (public.is_business_member(business_id));
drop policy if exists "Owners can manage expense categories" on public.expense_categories;
create policy "Owners can manage expense categories" on public.expense_categories for all using (public.is_business_owner(business_id)) with check (public.is_business_owner(business_id) and created_by = auth.uid());
drop policy if exists "Members can read expenses" on public.expenses;
create policy "Members can read expenses" on public.expenses for select using (public.is_business_member(business_id) and exists (select 1 from public.business_members m where m.business_id=expenses.business_id and m.user_id=auth.uid() and m.status='active' and (m.role='OWNER' or m.booth_id=expenses.booth_id)));
drop policy if exists "Members can read expense history" on public.expense_status_history;
create policy "Members can read expense history" on public.expense_status_history for select using (public.is_business_member(business_id));
grant select on public.expense_categories, public.expenses, public.expense_status_history to authenticated;
grant execute on function public.generate_expense_reference() to authenticated;